import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadAnton = makeLoadFont('Anton');
const loadInter = makeLoadFont('Inter');

// Load fonts at module level to ensure they block rendering until ready
const { fontFamily: antonFamily } = loadAnton();
const { fontFamily: interFamily } = loadInter();



export type ConcretePourProps = Record<string, any>;

const ConcretePour: React.FC<ConcretePourProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 6,
  primaryColor = "#8A949A",
  accentColor = "#E67E22",
  amount = 400,
  unitText = "m³",
  materialText = "OF CONCRETE",
  actionText = "TO LAY",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  const totalFrames = Math.floor(durationInSeconds * fps);

  // Timing constants
  const textStagger = 5;
  const pourStartFrame = 30;
  const pourEndFrame = totalFrames - 45; // Give it 1.5 seconds to settle at the end

  // Entrance animations for text block
  const numSpring = spring({ frame: frame - 5, fps, config: { damping: 14 } });
  const matSpring = spring({ frame: frame - (5 + textStagger), fps, config: { damping: 14 } });
  const actSpring = spring({ frame: frame - (5 + textStagger * 2), fps, config: { damping: 14 } });

  // Entrance animation for the pouring container
  const containerSpring = spring({ frame: frame - 15, fps, config: { damping: 16 } });

  // The main pouring progress (0 to 1)
  const pourProgress = interpolate(
    frame,
    [pourStartFrame, pourEndFrame],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.cubic),
    }
  );

  // Pulse effect for the active fill edge
  const pulse = interpolate(frame % 30, [0, 15, 30], [0.5, 1, 0.5]);
  const activeEdgeOpacity = pourProgress > 0 && pourProgress < 1 ? pulse : 0;

  // Derive the currently displayed number from the pour progress
  const displayAmount = Math.floor(pourProgress * amount);
  const formattedAmount = new Intl.NumberFormat("en-US").format(displayAmount);

  // SVG blueprint grid component safely handling patterns
  const BlueprintGrid = ({ color, size }: { color: string; size: number }) => (
    <svg
      width="100%"
      height="100%"
      xmlns="http://www.w3.org/2000/svg"
      style={{ position: "absolute", inset: 0 }}
    >
      <defs>
        <pattern id="rebarGrid" width={size} height={size} patternUnits="userSpaceOnUse">
          <path d={`M ${size} 0 L 0 0 0 ${size}`} fill="none" stroke={color} strokeWidth="2" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#rebarGrid)" />
    </svg>
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, color: "#fff", fontFamily: interFamily }}>
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "space-between",
          padding: `0 ${width * 0.1}px`,
          width: "100%",
          height: "100%",
          boxSizing: "border-box",
        }}
      >
        {/* Left Column: Typography & Metrics */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: height * 0.02,
            width: "50%",
          }}
        >
          {/* Animated Number + Unit */}
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              alignItems: "baseline",
              gap: width * 0.02,
              opacity: interpolate(numSpring, [0, 1], [0, 1]),
              transform: `translateY(${interpolate(numSpring, [0, 1], [50, 0])}px)`,
              transition: "none",
            }}
          >
            <span
              style={{
                fontFamily: antonFamily,
                fontSize: width * 0.1,
                lineHeight: 1,
                letterSpacing: "2px",
                whiteSpace: "nowrap",
                color: "#FFFFFF",
              }}
            >
              {formattedAmount}
            </span>
            <span
              style={{
                fontSize: width * 0.05,
                opacity: 0.8,
                fontWeight: 600,
              }}
            >
              {unitText}
            </span>
          </div>

          {/* Material Text */}
          <div
            style={{
              fontSize: width * 0.04,
              fontWeight: 800,
              letterSpacing: "4px",
              color: accentColor,
              textTransform: "uppercase",
              opacity: interpolate(matSpring, [0, 1], [0, 1]),
              transform: `translateY(${interpolate(matSpring, [0, 1], [30, 0])}px)`,
              transition: "none",
            }}
          >
            {materialText}
          </div>

          {/* Action Text */}
          <div
            style={{
              fontSize: width * 0.03,
              textTransform: "uppercase",
              letterSpacing: "2px",
              fontWeight: 500,
              opacity: interpolate(actSpring, [0, 1], [0, 0.6]),
              transform: `translateY(${interpolate(actSpring, [0, 1], [20, 0])}px)`,
              transition: "none",
            }}
          >
            {actionText}
          </div>
        </div>

        {/* Right Column: Visualization Graphic */}
        <div
          style={{
            width: width * 0.25,
            height: height * 0.6,
            position: "relative",
            opacity: interpolate(containerSpring, [0, 1], [0, 1]),
            transform: `scale(${interpolate(containerSpring, [0, 1], [0.9, 1])})`,
            transition: "none",
          }}
        >
          {/* Main Container / Formwork */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              border: `6px solid ${accentColor}`,
              borderRadius: `0 0 ${width * 0.015}px ${width * 0.015}px`,
              borderTop: "none",
              overflow: "hidden",
              backgroundColor: "rgba(0, 0, 0, 0.3)",
              boxShadow: "inset 0px 10px 30px rgba(0,0,0,0.5)",
            }}
          >
            {/* Background Rebar Grid */}
            <div style={{ position: "absolute", inset: 0, opacity: 0.3 }}>
              <BlueprintGrid color={accentColor} size={width * 0.02} />
            </div>

            {/* The Concrete Filling Up */}
            <div
              style={{
                position: "absolute",
                bottom: 0,
                left: 0,
                right: 0,
                height: `${pourProgress * 100}%`,
                backgroundColor: primaryColor,
                display: "flex",
                flexDirection: "column",
                justifyContent: "flex-start",
                transition: "none",
                boxShadow: "0px -4px 15px rgba(0,0,0,0.4)",
              }}
            >
              {/* Active Pulse Line at the surface */}
              <div
                style={{
                  width: "100%",
                  height: "8px",
                  backgroundColor: accentColor,
                  opacity: activeEdgeOpacity,
                  transition: "none",
                }}
              />
            </div>
          </div>
          
          {/* Top structural brackets holding the formwork */}
          <div style={{ position: "absolute", top: "-6px", left: "-10px", width: "20px", height: "12px", backgroundColor: accentColor }} />
          <div style={{ position: "absolute", top: "-6px", right: "-10px", width: "20px", height: "12px", backgroundColor: accentColor }} />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ConcretePour;